	@ParameterizedTest
	@EnumSource(PullScope.class)
	void delayedFinalResultRetainsEvaluationCaptureAcrossPullScopes(PullScope pullScope, @TempDir File directory) {
		RecordingFactory factory = new RecordingFactory(true);
		LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc")
				.setNativeEvaluationEnabled(true)
				.setSketchEstimatorEnabled(false));
		store.setEvaluationStrategyFactory(factory);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (var connection = repository.getConnection()) {
				ValueFactory values = repository.getValueFactory();
				seed(connection, values);
				try (LmdbBenchmarkQueryPlan plan = LmdbBenchmarkQueryPlan.prepare(store, connection, ROOT_QUERY, 0,
						true, LmdbBenchmarkQueryPlan.RuntimeTelemetryMode.SAMPLED_FULL)) {
					NativeExecutionObservation.Capture owner = NativeExecutionObservation.begin(64, 64);
					NativeExecutionObservation.Capture enclosing = NativeExecutionObservation.begin(64, 64);
					CloseableIteration<BindingSet> result;
					try (var ignored = enclosing.enter()) {
						try (var scope = owner.enter()) {
							result = plan.evaluate();
							assertSame(owner, NativeExecutionObservation.current());
						}
						assertSame(enclosing, NativeExecutionObservation.current());
					}
					assertNull(NativeExecutionObservation.current());
					assertTrue(factory.delayedResult.get() instanceof QueryEvaluationStep.DelayedEvaluationIteration);
					assertEquals(0, factory.delayedEvaluations.get(), "the actual final result must remain lazy");
					assertEquals(NativeExecutionObservation.Coverage.UNOBSERVED,
							owner.snapshot().coverage(NativeExecutionObservation.RegionKind.ROW));
					NativeExecutionObservation.Capture pull = switch (pullScope) {
					case NONE -> null;
					case OTHER -> NativeExecutionObservation.begin(64, 64);
					case DISABLED -> NativeExecutionObservation.disabled();
					};
					List<BindingSet> actual;
					if (pull == null) {
						actual = drainInScope(result, null);
					} else {
						try (var ignored = enclosing.enter()) {
							try (var scope = pull.enter()) {
								actual = drainInScope(result, pull);
							}
							assertSame(enclosing, NativeExecutionObservation.current());
						}
					}
					assertNull(NativeExecutionObservation.current());
					assertEquals(bag(rootRows(values)), bag(actual));
					assertEquals(1, factory.optimizations.get(), "preparing must optimize exactly once");
					assertEquals(1, factory.finalEntries.get(), "the final tuple consumer must compile exactly once");
					assertSame(factory.optimized.get(), factory.finalRoot.get());
					assertEquals(1, factory.delayedEvaluations.get(),
							"the final result must be evaluated exactly once");
					var receipt = owner.snapshot();
					assertEquals(NativeExecutionObservation.Coverage.OBSERVED,
							receipt.coverage(NativeExecutionObservation.RegionKind.ROW));
					assertEquals(1L, receipt.events()
							.stream()
							.filter(event -> event.regionKind() == NativeExecutionObservation.RegionKind.ROW
									&& event.phase() == NativeExecutionObservation.Phase.COMPLETED)
							.count(), "the actual native row owner must finish in its opening capture");
					assertTrue(receipt.events()
							.stream()
							.noneMatch(event -> event.phase() == NativeExecutionObservation.Phase.PARTIAL
									|| event.phase() == NativeExecutionObservation.Phase.FAILED
									|| event.phase() == NativeExecutionObservation.Phase.CANCELLED));
					if (pull != null) {
						assertEquals(pullScope == PullScope.DISABLED ? NativeExecutionObservation.Coverage.DISABLED
								: NativeExecutionObservation.Coverage.UNOBSERVED, pull.snapshot().coverage());
					}
					assertEquals(NativeExecutionObservation.Coverage.UNOBSERVED, enclosing.snapshot().coverage());
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	private enum PullScope {
		NONE,
		OTHER,
		DISABLED
	}

	@Test
	void observedEvaluationsOwnIndependentReceiptsOnAReusedPlan(@TempDir File directory) {
		RecordingFactory factory = new RecordingFactory(true);
		LmdbStore store = nativeStore(directory, factory);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (var connection = repository.getConnection()) {
				ValueFactory values = repository.getValueFactory();
				seed(connection, values);
				var enclosing = NativeExecutionObservation.begin(64, 64);
				try (LmdbBenchmarkQueryPlan plan = LmdbBenchmarkQueryPlan.prepare(store, connection, ROOT_QUERY, 0,
						true, LmdbBenchmarkQueryPlan.RuntimeTelemetryMode.SAMPLED_FULL);
						var ignored = enclosing.enter();
						var complete = plan.evaluateObserved(64, 64);
						var partial = plan.evaluateObserved(64, 64)) {
					assertSame(enclosing, NativeExecutionObservation.current());
					var initial = complete.snapshot();
					assertEquals(NativeExecutionObservation.Coverage.UNOBSERVED, initial.coverage());
					assertEquals(NativeExecutionObservation.Coverage.UNOBSERVED, partial.snapshot().coverage());
					assertNotEquals(initial.invocationId(), partial.snapshot().invocationId());
					assertEquals(bag(rootRows(values)), bag(drainInScope(complete.result(), enclosing)));
					assertTrue(partial.result().hasNext());
					assertTrue(rootRows(values).contains(partial.result().next()));
					partial.result().close();
					assertRowTerminal(complete.snapshot(), NativeExecutionObservation.Phase.COMPLETED);
					assertRowTerminal(partial.snapshot(), NativeExecutionObservation.Phase.PARTIAL);
					assertEquals(NativeExecutionObservation.Coverage.UNOBSERVED, initial.coverage(),
							"an earlier snapshot is detached from later events");
					assertEquals(1, factory.optimizations.get());
					assertEquals(1, factory.finalEntries.get());
					assertEquals(2, factory.delayedEvaluations.get());
				}
				assertNull(NativeExecutionObservation.current());
				assertEquals(NativeExecutionObservation.Coverage.UNOBSERVED, enclosing.snapshot().coverage());
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void concurrentEvaluationsOfOnePreparedPlanKeepReceiptsSeparate(@TempDir File directory) throws Exception {
		CountDownLatch bothResultsOpened = new CountDownLatch(2);
		RecordingFactory factory = new RecordingFactory(true, result -> {
			bothResultsOpened.countDown();
			try {
				if (!bothResultsOpened.await(20, TimeUnit.SECONDS)) {
					throw new AssertionError("both actual result openings must overlap");
				}
			} catch (InterruptedException interrupted) {
				Thread.currentThread().interrupt();
				throw new IllegalStateException(interrupted);
			}
			return result;
		});
		LmdbStore store = nativeStore(directory, factory);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (var connection = repository.getConnection()) {
				ValueFactory values = repository.getValueFactory();
				seed(connection, values);
				try (LmdbBenchmarkQueryPlan plan = LmdbBenchmarkQueryPlan.prepare(store, connection, ROOT_QUERY, 0,
						true, LmdbBenchmarkQueryPlan.RuntimeTelemetryMode.SAMPLED_FULL);
						var first = plan.evaluateObserved(64, 64);
						var second = plan.evaluateObserved(64, 64)) {
					CountDownLatch ready = new CountDownLatch(2);
					CountDownLatch start = new CountDownLatch(1);
					var executor = Executors.newFixedThreadPool(2);
					Future<List<BindingSet>> firstRows = null;
					Future<List<BindingSet>> secondRows = null;
					try {
						firstRows = executor.submit(() -> {
							ready.countDown();
							if (!start.await(20, TimeUnit.SECONDS)) {
								throw new AssertionError("concurrent evaluations were not released");
							}
							return drainInScope(first.result(), null);
						});
						secondRows = executor.submit(() -> {
							ready.countDown();
							if (!start.await(20, TimeUnit.SECONDS)) {
								throw new AssertionError("concurrent evaluations were not released");
							}
							return drainInScope(second.result(), null);
						});
						assertTrue(ready.await(20, TimeUnit.SECONDS));
						start.countDown();
						assertEquals(bag(rootRows(values)), bag(firstRows.get(30, TimeUnit.SECONDS)));
						assertEquals(bag(rootRows(values)), bag(secondRows.get(30, TimeUnit.SECONDS)));
					} finally {
						start.countDown();
						if (firstRows != null) {
							firstRows.cancel(true);
						}
						if (secondRows != null) {
							secondRows.cancel(true);
						}
						executor.shutdownNow();
						assertTrue(executor.awaitTermination(30, TimeUnit.SECONDS),
								"evaluation workers must settle before the prepared plan closes");
					}
					var firstReceipt = first.snapshot();
					var secondReceipt = second.snapshot();
					assertNotEquals(firstReceipt.invocationId(), secondReceipt.invocationId());
					assertRowTerminal(firstReceipt, NativeExecutionObservation.Phase.COMPLETED);
					assertRowTerminal(secondReceipt, NativeExecutionObservation.Phase.COMPLETED);
					long firstNative = firstReceipt.events()
							.stream()
							.filter(event -> event.regionKind() == NativeExecutionObservation.RegionKind.ROW)
							.findFirst()
							.orElseThrow()
							.nativeEvaluationId();
					long secondNative = secondReceipt.events()
							.stream()
							.filter(event -> event.regionKind() == NativeExecutionObservation.RegionKind.ROW)
							.findFirst()
							.orElseThrow()
							.nativeEvaluationId();
					assertNotEquals(firstNative, secondNative);
					assertEquals(1, factory.optimizations.get());
					assertEquals(1, factory.finalEntries.get());
					assertEquals(2, factory.delayedEvaluations.get());
				}
			}
		} finally {
			repository.shutDown();
		}
	}

